INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00026000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 26), 'unit26-lesson1', 'Either … or: Connecting Alternatives', 'Either … or is a correlative conjunction used to connect things of the same type — phrases, clauses, or words. It presents two alternatives where only one is true or happens.', '{"details":[{"concept":"Either + noun/clause + or + noun/clause","explanation":"Use ''either … or'' to join two alternatives. The two parts joined must be of the same grammatical type.","example":"Either he or she cooks dinner.","burmese":"ကျပ် တိမႄးမြုံပ် ကျအိ လူပ်စော်ပ၌ဦစော်းမြုံပ၌ဦး့"},{"concept":"Either + noun/clause + or + noun/clause","explanation":"When ''either … or'' connects two verbs sharing the same subject, place ''either'' before the first verb.","example":"He either washes the dishes or irons the clothes.","burmese":"ကျပ် ပုံါား စော် တိမႄးမြုံပ် အိ လူပ်တော်စော်းမြုံပ၌ဦး့"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00026001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 26), 'unit26-lesson2', 'Subject-Verb Agreement with Either … or', 'If one subject is singular and the other is plural, the verb form agrees with the subject that is nearest to the verb. This is an important rule to remember when using ''either … or'' with compound subjects.', '{"details":[{"concept":"Verb agrees with nearest subject","explanation":"When the two subjects joined by ''either … or'' differ in number, the verb takes the form of the nearer subject.","example":"Either my parents or my brother works hard to support the family.","burmese":"စော်္ျပ် မျတေါ့ စော် တိမႄးမြုံပ် စော်စိအန် အိ လူပ်္ျားးမြုံပော်း၊"},{"concept":"Verb agrees with nearest subject","explanation":"The verb matches the number (singular or plural) of the subject closest to it.","example":"Either the cat or the dogs are outside.","burmese":"အိမႄးမြုံပ် တိမႄးမြုံပ် ကျအိ လူပ့်"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00026000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 26), 'unit26-ex1', 'multiple_choice', 'Combine the following sentences using ''either … or''.', '[{"id":2601,"question":"She can have tea. Or she can have coffee. Combine using ''either … or''.","options":["She can have either tea or coffee","Either she can tea or coffee","She either have tea or coffee"],"answer":"She can have either tea or coffee","explanation":"Place ''either'' before the first alternative and ''or'' before the second. ''Can have'' stays at the beginning. ''Either … or'' ကို noun နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2602,"question":"He keeps the keys himself. Or he leaves them with his wife. Combine using ''either … or''.","options":["He either keeps the keys himself or leaves them with his wife","Either he keeps the keys or himself leaves them","He keeps either the keys himself or his wife"],"answer":"He either keeps the keys himself or leaves them with his wife","explanation":"When both clauses share the same subject, place ''either'' before the first verb. ''Either … or'' ကို verb phrase နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2603,"question":"He may attend the function. Or his wife may attend the function. Combine using ''either … or''.","options":["Either he or his wife may attend the function","He may either attend his wife or the function","Either he attends or his wife the function"],"answer":"Either he or his wife may attend the function","explanation":"Use ''Either + subject + or + subject'' before the verb. The two subjects are joined by ''either … or''. ''Either … or'' ကို subject နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2604,"question":"Give me freedom. Or give me death. Combine using ''either … or''.","options":["Give me either freedom or death","Either give me freedom or death","Give either me freedom or me death"],"answer":"Give me either freedom or death","explanation":"Place ''either'' before the first alternative and ''or'' before the second within the object. ''Either … or'' ကို object နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2605,"question":"He must have done this. Or his brother must have done this. Combine using ''either … or''.","options":["Either he or his brother must have done this","He must either have done this or his brother","Either he or his brother done this must have"],"answer":"Either he or his brother must have done this","explanation":"Use ''Either + subject + or + subject'' before the modal verb. ''Either … or'' ကို subject နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2606,"question":"She will weep. Or she will die. Combine using ''either … or''.","options":["She will either weep or die","Either she weeps or dies will","She either will weep or will die"],"answer":"She will either weep or die","explanation":"When both clauses share the same subject, place ''either'' between the modal verb and the first verb. ''Either … or'' ကို verb နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2607,"question":"He is a fool. He is a mad man to accept this task. Combine using ''either … or''.","options":["He is either a fool or a mad man to accept this task","Either he is a fool or mad man a task","He is a either fool or a mad man"],"answer":"He is either a fool or a mad man to accept this task","explanation":"Place ''either'' after the verb ''is'' and before the first noun phrase, with ''or'' before the second. ''Either … or'' ကို noun phrase နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2608,"question":"Nick can play golf. Nick can play football. Combine using ''either … or''.","options":["Nick can play either golf or football","Either Nick can play golf or football","Nick either can play golf or football"],"answer":"Nick can play either golf or football","explanation":"Place ''either'' before the first object and ''or'' before the second. The subject and auxiliary stay at the beginning. ''Either … or'' ကို object နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2609,"question":"You can write with a pen. You can write with a pencil. Combine using ''either … or''.","options":["You can write with either a pen or a pencil","Either you can write with a pen or pencil","You can either write with a pen or a pencil"],"answer":"You can write with either a pen or a pencil","explanation":"Place ''either'' before the first prepositional phrase alternative and ''or'' before the second. ''Either … or'' ကို prepositional phrase နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2610,"question":"My mom likes mangoes. Or she likes bananas. Combine using ''either … or''.","options":["My mom likes either mangoes or bananas","Either my mom likes mangoes or bananas","My mom either likes mangoes or she likes bananas"],"answer":"My mom likes either mangoes or bananas","explanation":"Place ''either'' before the first object and ''or'' before the second. The subject and verb stay at the beginning. ''Either … or'' ကို object နှစ်ခုကြားမှာ ထားပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

