INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00027000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 27), 'unit27-lesson1', 'Neither … nor: Connecting Negative Alternatives', 'Neither … nor is used to connect the same kind of word or phrase in a sentence. Neither makes a negative statement about two people or things. It means ''not one and not the other''.', '{"details":[{"concept":"Neither + noun/verb/phrase + nor + noun/verb/phrase","explanation":"Use ''neither … nor'' to join two negative alternatives. Both parts must be the same grammatical type.","example":"I like neither banana nor apple.","burmese":"စော် စိမႄးမြုံပ် ကျဆျဥမ် မျအိ ါူးူိ မျအိ ါူးူိ မျကျုံပ၌ဦး့"},{"concept":"Neither + verb + nor + verb","explanation":"When both clauses share the same subject, place ''neither'' before the first verb and ''nor'' before the second.","example":"He neither drinks nor smokes.","burmese":"ကျပ် စော် အိ လူပ် စော် အိ လူပ်မျကျုံပ၌ဦး့"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00027001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 27), 'unit27-lesson2', 'Subject-Verb Agreement with Neither … nor', 'If one subject is singular and the other is plural, the verb form agrees with the subject that is nearest to the verb. This rule is the same as with ''either … or''.', '{"details":[{"concept":"Verb agrees with nearest subject","explanation":"When the two subjects joined by ''neither … nor'' differ in number, the verb takes the form of the nearer subject.","example":"Neither my parents nor my brother likes pineapple.","burmese":"စော်္ျပ် မျတေါ့ အိ တိမႄးမြုံပ် စော်စိအန် အိ လူပ်ကျမႄးမြုံပ၌ဦး့"},{"concept":"Neither I nor my friends + plural verb","explanation":"When the nearest subject is plural, use the plural verb form.","example":"Neither I nor my friends go to the party.","burmese":"စော် အိ စော် စိအန်္ျပ် အိ လူပ် မျကျုံပ၌ဦး့"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00027000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 27), 'unit27-ex1', 'multiple_choice', 'Combine the following negative sentences using ''neither … nor''.', '[{"id":2701,"question":"I don''t like Stephen. I don''t like Peter. Combine using ''neither … nor''.","options":["I like neither Stephen nor Peter","I neither like Stephen or Peter","Neither I like Stephen nor Peter"],"answer":"I like neither Stephen nor Peter","explanation":"Place ''neither'' before the first noun and ''nor'' before the second. The subject and verb stay at the beginning. ''Neither … nor'' ကို object နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2702,"question":"He wasn''t wearing a shirt. He wasn''t wearing a coat. Combine using ''neither … nor''.","options":["He was wearing neither a shirt nor a coat","He neither was wearing a shirt nor a coat","Neither he was wearing a shirt or a coat"],"answer":"He was wearing neither a shirt nor a coat","explanation":"Place ''neither'' before the first noun phrase and ''nor'' before the second. The subject and verb stay at the beginning. ''Neither … nor'' ကို noun phrase နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2703,"question":"He will not come here. He will not send a representative. Combine using ''neither … nor''.","options":["He will come here neither send a representative","He will neither come here nor send a representative","Neither he will come here nor send a representative"],"answer":"He will neither come here nor send a representative","explanation":"Place ''neither'' after the modal verb and before the first verb phrase, with ''nor'' before the second. ''Neither … nor'' ကို verb phrase နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2704,"question":"Don''t be a borrower. Don''t be a lender. Combine using ''neither … nor''.","options":["Be neither a borrower nor a lender","Neither be a borrower or be a lender","Be neither a borrower or a lender"],"answer":"Be neither a borrower nor a lender","explanation":"Use ''neither'' after the verb ''be'' and ''nor'' before the second noun phrase. ''Neither … nor'' ကို noun phrase နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2705,"question":"She can''t read English. She can''t write English. Combine using ''neither … nor''.","options":["She can read neither English nor English","She can neither read nor write English","Neither she can read nor write English"],"answer":"She can neither read nor write English","explanation":"Place ''neither'' after the modal verb and before the first verb, with ''nor'' before the second verb. The object comes after both. ''Neither … nor'' ကို verb နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2706,"question":"Shyam is not mad. He is not foolish. Combine using ''neither … nor''.","options":["Shyam is neither mad nor foolish","Shyam neither is mad or foolish","Neither Shyam is mad nor foolish"],"answer":"Shyam is neither mad nor foolish","explanation":"Place ''neither'' after the verb ''is'' and ''nor'' before the second adjective. ''Neither … nor'' ကို adjective နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2707,"question":"Sheela does not spend money. Her parents do not spend money. Combine using ''neither … nor''.","options":["Neither Sheela nor her parents spend money","Neither Sheela or her parents spends money","Sheela neither spends money nor her parents"],"answer":"Neither Sheela nor her parents spend money","explanation":"When subjects differ in number, the verb agrees with the nearest subject. ''Parents'' is plural so use ''spend''. ''Neither … nor'' ကို subject နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2708,"question":"He is not honest. He is not punctual. Combine using ''neither … nor''.","options":["He is neither honest nor punctual","He neither is honest nor punctual","Neither he is honest nor punctual"],"answer":"He is neither honest nor punctual","explanation":"Place ''neither'' after the verb ''is'' and ''nor'' before the second adjective. ''Neither … nor'' ကို adjective နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2709,"question":"I don''t know Hindi. I don''t know Tamil. Combine using ''neither … nor''.","options":["I know neither Hindi nor Tamil","I neither know Hindi or Tamil","Neither I know Hindi nor Tamil"],"answer":"I know neither Hindi nor Tamil","explanation":"Place ''neither'' before the first object and ''nor'' before the second. The subject and verb stay at the beginning. ''Neither … nor'' ကို object နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2710,"question":"The minister did not attend the party. His followers did not attend the party. Combine using ''neither … nor''.","options":["Neither the minister nor his followers attended the party","Neither the minister or his followers attended the party","The minister neither attended nor his followers the party"],"answer":"Neither the minister nor his followers attended the party","explanation":"Use ''Neither + subject + nor + subject'' before the verb. The two subjects are joined by ''neither … nor''. ''Neither … nor'' ကို subject နှစ်ခုကြားမှာ ထားပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

